// ===================== APP STATE =====================
let currentChapter = 0;
let savedWords = JSON.parse(localStorage.getItem("savedWords") || "[]");
let viewMode = "grid";
let searchTerm = "";

// ===================== INIT =====================
function init() {
  document.getElementById("totalWords").textContent = getTotalWords();
  document.getElementById("savedCount").textContent = savedWords.length;
  renderChapterList();
  selectChapter(0);
}

function getTotalWords() {
  return chapters.reduce((sum, ch) => sum + ch.words.length, 0);
}

// ===================== SIDEBAR =====================
function renderChapterList() {
  const list = document.getElementById("chapterList");
  list.innerHTML = chapters
    .map(
      (ch, i) => `
          <div class="ch-item ${i === currentChapter ? "active" : ""}" onclick="selectChapter(${i})">
            <div class="ch-icon">${ch.icon}</div>
            <div class="ch-info">
              <div class="ch-name">${ch.name}</div>
              <div class="ch-count">${ch.words.length} كلمة • ${ch.level}</div>
              <div class="ch-progress"><div class="ch-progress-fill" style="width:${getChapterProgress(i)}%"></div></div>
            </div>
          </div>
        `,
    )
    .join("");
}

function getChapterProgress(i) {
  const ch = chapters[i];
  const saved = ch.words.filter((w) => savedWords.includes(w[0])).length;
  return ch.words.length ? Math.round((saved / ch.words.length) * 100) : 0;
}

// ===================== CHAPTER SELECTION =====================
function selectChapter(index) {
  currentChapter = index;
  const ch = chapters[index];

  document.getElementById("chapterHeader").innerHTML = `
          <div class="chapter-header">
            <div class="ch-emoji">${ch.icon}</div>
            <h1>${ch.name}</h1>
            <p>المستوى: ${ch.level} | تعلم أهم الكلمات الألمانية في هذا الموضوع</p>
            <div class="ch-meta">
              <span>📝 ${ch.words.length} كلمة</span>
              <span>📊 المستوى ${ch.level}</span>
              <span>⭐ ${ch.words.filter((w) => savedWords.includes(w[0])).length} محفوظة</span>
            </div>
          </div>
        `;

  const prog = getChapterProgress(index);
  document.getElementById("progPercent").textContent = prog + "%";
  document.getElementById("progFill").style.width = prog + "%";

  renderWords(ch.words);
  renderChapterList();

  // Close sidebar on mobile
  document.getElementById("sidebar").classList.remove("open");
}

// ===================== RENDER WORDS =====================
function renderWords(words) {
  const grid = document.getElementById("wordsGrid");
  const filtered = searchTerm
    ? words.filter(
        (w) =>
          w[0].toLowerCase().includes(searchTerm.toLowerCase()) ||
          w[2].includes(searchTerm),
      )
    : words;

  grid.innerHTML = filtered
    .map((w, i) => {
      const isSaved = savedWords.includes(w[0]);
      return `
          <div class="word-card" style="animation-delay:${i * 0.05}s" onclick="openModal('${w[0]}','${w[2]}','${w[3]}','${w[4] || ""}','${w[5] || ""}')">
            <div class="wc-top">
              <div>
                <div class="wc-de">${w[0]}</div>
              </div>
              <span class="wc-type">${w[1]}</span>
            </div>
            <div class="wc-ar">${w[2]}</div>
            <div class="wc-pron">🔈 ${w[3]}</div>
            ${
              w[4]
                ? `<div class="wc-example">
              <div class="wc-ex-de">📝 ${w[4]}</div>
              <div class="wc-ex-ar">${w[5]}</div>
            </div>`
                : ""
            }
            <div class="wc-actions">
              <button class="wc-btn" onclick="event.stopPropagation();speak('${w[0]}')" title="استمع">🔊</button>
              <button class="wc-btn ${isSaved ? "saved" : ""}" onclick="event.stopPropagation();toggleSave('${w[0]}')" title="حفظ">⭐</button>
            </div>
          </div>
        `;
    })
    .join("");

  if (!filtered.length) {
    grid.innerHTML =
      '<div style="text-align:center;padding:60px;color:var(--text3);font-size:18px;">😕 لم يتم العثور على نتائج</div>';
  }
}

// ===================== SEARCH =====================
function handleSearch() {
  searchTerm = document.getElementById("searchInput").value.trim();
  if (searchTerm) {
    // Search across all chapters
    const allWords = [];
    chapters.forEach((ch) => ch.words.forEach((w) => allWords.push(w)));
    renderWords(allWords);
  } else {
    renderWords(chapters[currentChapter].words);
  }
}

// ===================== SPEAK =====================
function speak(word) {
  if ("speechSynthesis" in window) {
    const u = new SpeechSynthesisUtterance(word);
    u.lang = "de-DE";
    u.rate = 0.75;
    speechSynthesis.speak(u);
  }
}

// ===================== SAVE =====================
function toggleSave(word) {
  const idx = savedWords.indexOf(word);
  if (idx > -1) {
    savedWords.splice(idx, 1);
    showToast("تم إزالة الكلمة من المحفوظات");
  } else {
    savedWords.push(word);
    showToast("تم حفظ الكلمة ⭐");
  }
  localStorage.setItem("savedWords", JSON.stringify(savedWords));
  document.getElementById("savedCount").textContent = savedWords.length;
  selectChapter(currentChapter);
}

function showSaved() {
  if (!savedWords.length) {
    showToast("لا توجد كلمات محفوظة بعد");
    return;
  }
  const allWords = [];
  chapters.forEach((ch) =>
    ch.words.forEach((w) => {
      if (savedWords.includes(w[0])) allWords.push(w);
    }),
  );
  document.getElementById("chapterHeader").innerHTML = `
          <div class="chapter-header">
            <div class="ch-emoji">⭐</div>
            <h1>الكلمات المحفوظة</h1>
            <p>${allWords.length} كلمة محفوظة</p>
          </div>`;
  renderWords(allWords);
}

// ===================== MODAL =====================
function openModal(de, ar, pron, exDe, exAr) {
  document.getElementById("modalDe").textContent = de;
  document.getElementById("modalAr").textContent = ar;
  document.getElementById("modalPron").textContent = "🔈 النطق: " + pron;
  document.getElementById("modalExample").innerHTML = exDe
    ? `<div style="color:var(--blue);font-weight:600;margin-bottom:5px;">📝 ${exDe}</div><div style="color:var(--text2)">${exAr}</div>`
    : "";
  document.getElementById("modal").classList.add("show");
  speak(de);
}

function closeModal(e) {
  if (e.target === e.currentTarget) e.currentTarget.classList.remove("show");
}

// ===================== VIEW =====================
function setView(mode, btn) {
  viewMode = mode;
  const grid = document.getElementById("wordsGrid");
  grid.classList.toggle("list-view", mode === "list");
  document
    .querySelectorAll(".v-btn")
    .forEach((b) => b.classList.remove("active"));
  btn.classList.add("active");
}

// ===================== DARK MODE =====================
function toggleDark() {
  document.body.classList.toggle("dark");
  localStorage.setItem("dark", document.body.classList.contains("dark"));
}

if (localStorage.getItem("dark") === "true")
  document.body.classList.add("dark");

// ===================== SIDEBAR TOGGLE =====================
function toggleSidebar() {
  document.getElementById("sidebar").classList.toggle("open");
}

// ===================== TOAST =====================
function showToast(msg) {
  const t = document.getElementById("toast");
  t.textContent = msg;
  t.classList.add("show");
  setTimeout(() => t.classList.remove("show"), 2500);
}

// ===================== EXPORT =====================
function exportData() {
  const data = JSON.stringify(chapters, null, 2);
  const blob = new Blob([data], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "german-words-5000.json";
  a.click();
  showToast("تم تصدير البيانات بنجاح 📥");
}

// ===================== KEYBOARD =====================
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape")
    document.getElementById("modal").classList.remove("show");
});

// ===================== START =====================
init();
